def transform(grid):
    H=len(grid);W=len(grid[0])
    # separator color: most common full-row/col color
    sep=6  # determined per grid below
    from collections import Counter
    # find rows that are uniform
    def uniform(r): return len(set(r))==1
    ridx=[];cur=[]
    for i,r in enumerate(grid):
        if uniform(r):
            if cur: ridx.append(cur)
            cur=[]
        else: cur.append(i)
    if cur: ridx.append(cur)
    cidx=[];cur=[]
    for c in range(W):
        col={grid[r][c] for r in range(H)}
        if len(col)==1:
            if cur: cidx.append(cur)
            cur=[]
        else: cur.append(c)
    if cur: cidx.append(cur)
    # colors: accent vs background
    vals=Counter(grid[r][c] for i in ridx for ri in i for j in cidx for c_ in j for r in [ri] for c in [c_])
    # separator color = uniform row color
    sepcolor=grid[next(i for i,r in enumerate(grid) if uniform(r))][0]
    blockvals=[grid[ri][ci] for ri in ridx[0] for ci in cidx[0]]
    bg=Counter(blockvals).most_common(1)[0][0]
    out=[]
    for i in range(len(ridx)):
        row=[]
        for j in range(len(cidx)):
            n=sum(1 for ri in ridx[i] for ci in cidx[j] if grid[ri][ci]!=sepcolor and grid[ri][ci]!=bg)
            row.append(1 if n>=2 else bg)
        out.append(row)
    return out
